import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a Recipient that reverts on transferFrom
        RevertingRecipient recip = new RevertingRecipient();
        address[] memory tos = new address[](2);
        tos[0] = address(0xdead);
        tos[1] = address(recip);
        uint[] memory v = new uint[](2);
        v[0] = 1;
        v[1] = 1;
        // The allowed caller
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Wrap call in try/catch to capture revert/return
        bool success;
        try c.transfer(tos, v) {
            success = true;
        } catch {
            success = false;
        }
        // In reference: reverts (success == false); in buggy: returns true (success == true)
        // We assert that the call succeeds, which holds on buggy but fails on reference.
        assertTrue(success, "bug should succeed but reference reverts");
    }
}

contract RevertingRecipient {
    // fallback that reverts for any call
    fallback() external payable { revert("always revert"); }
    receive() external payable { revert("always revert"); }
}

