        address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        address badRecipient = address(0xdead);
        address goodRecipient = address(0xbeef);
        address[] memory tos = new address[](2);
        tos[0] = badRecipient;
        tos[1] = goodRecipient;
        uint[] memory values = new uint[](2);
        values[0] = 1;
        values[1] = 1;

        vm.prank(owner);
        bool ok;
        try c.transfer(tos, values) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts => ok is false; bug returns false => catch is NOT triggered => ok is true
        // Assert that ok is false (the reference behavior); on the bug it will be true, failing the test
        assertTrue(!ok);
    }
}
